
/* ============================================================
   ARIBA V70 — إضافة فقط، تبويب جديد بالكامل "نماذج" — بدون لمس
   أي كود أو صفحة أو دالة موجودة في البرنامج. كل حاجة هنا بتتضاف
   للصفحة ديناميكيًا: عنصر قائمة جانبية جديد، صفحة جديدة، ودوال
   طباعة مستقلة لسبع نماذج (مباشرة عمل، استلام عهدة تقنية، تمديد
   فترة التجربة، إشعار إنهاء فترة التجربة، إخلاء طرف، شهادة خبرة،
   نموذج تقييم فترة التجربة) بنفس هوية الشركة البصرية (الخطاب
   الرسمي بالشعار والألوان) اللي كانت مستخدمة فعليًا في نماذج
   الشركة القديمة.
   ============================================================ */
(function(){
  'use strict';

  /* ---------- خط الشركة + خلفية الخطاب الرسمي (Base64، مستقلة تمامًا عن باقي الباتشات) ---------- */
  var FONT_CSS =
    '@font-face{font-family:"ARIBA Two";src:url(data:font/ttf;base64,) format("truetype");font-weight:300 400;font-style:normal}'+
    '@font-face{font-family:"ARIBA Two";src:url(data:font/ttf;base64,) format("truetype");font-weight:500 600;font-style:normal}'+
    '@font-face{font-family:"ARIBA Two";src:url(data:font/ttf;base64,) format("truetype");font-weight:700 900;font-style:normal}';
  var HEADER_IMG = 'data:image/jpeg;base64,';
  var FOOTER_IMG = 'data:image/jpeg;base64,';

  /* ---------- أدوات مساعدة عامة ---------- */
  function tfD(v){ if(!v) return '\u2014'; try{ return new Date(v).toLocaleDateString('ar-SA-u-ca-gregory-nu-latn'); }catch(e){ return v; } }
  function tfDEn(v){ if(!v) return '____/____/________'; try{ var d=new Date(v); return d.toLocaleDateString('en-GB'); }catch(e){ return v; } }
  function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }

  function tfEmps(){
    try{
      var a = (typeof window.v60all === 'function') ? window.v60all() :
              ((typeof window.aEmps === 'function') ? window.aEmps().concat(typeof window.tEmps==='function'?window.tEmps():[]) : []);
      return Array.isArray(a) ? a : [];
    }catch(e){ return []; }
  }

  function tfSelectedEmp(){
    var sel = document.getElementById('TFE');
    if(!sel || !sel.value) return null;
    var id = sel.value;
    return tfEmps().find(function(x){ return String(x.id) === String(id); }) || null;
  }

  function tfRequireEmp(){
    var e = tfSelectedEmp();
    if(!e){ if(typeof toast==='function') toast('اختر الموظف أولاً', 'ter'); }
    return e;
  }

  /* ---------- إطار الخطاب الرسمي (هيدر + فوتر بنفس تصميم أوراق الشركة الأصلية) ---------- */
  var DOC_CSS =
    '<style>'+FONT_CSS+
    '@page{size:A4;margin:0}'+
    '*{box-sizing:border-box}'+
    'body{font-family:"ARIBA Two","Segoe UI",Tahoma,Arial,sans-serif;color:#14231d;margin:0;line-height:1.55;font-size:13.5px}'+
    '.doc{width:100%;max-width:210mm;margin:0 auto;min-height:297mm;position:relative;padding:0 16mm}'+
    '.lh-head{width:calc(100% + 32mm);display:block;margin:0 -16mm 8mm -16mm;max-width:none}'+
    '.lh-foot{width:100%;display:block;position:fixed;bottom:0;left:0}'+
    '.doc-body{padding-bottom:14mm}'+
    '.doc-title{text-align:center;font-size:19px;font-weight:900;color:#014D3D;margin:2mm 0 5mm}'+
    '.doc-title .en{display:block;font-size:13px;font-weight:700;color:#017a5f;margin-top:1mm}'+
    '.meta-row{display:flex;justify-content:space-between;font-size:11.5px;color:#555;margin-bottom:4mm}'+
    'table.tf-info{width:100%;border-collapse:collapse;margin-bottom:4mm;border:1px solid #d8e2de;border-radius:6px;overflow:hidden}'+
    'table.tf-info td{padding:6px 11px;border-bottom:1px solid #e5ece9;font-size:12px}'+
    'table.tf-info td.tf-lbl{background:#eef5f2;color:#014D3D;font-weight:800;width:20%;font-size:11.5px}'+
    'table.tf-info td.tf-val{width:30%;font-weight:600}'+
    'table.tf-info td b{color:#014D3D}'+
    '.tf-info-title{font-size:12px;color:#014D3D;font-weight:800;margin-bottom:2mm;padding-bottom:1.5mm;border-bottom:1.5px solid #014D3D}'+
    'table.tf-bi{width:100%;border-collapse:collapse;margin-bottom:4mm;border:1px solid #d8e2de}'+
    'table.tf-bi th{background:#014D3D;color:#fff;padding:5px 8px;font-size:11.5px}'+
    'table.tf-bi td{padding:5px 9px;border-bottom:1px solid #e5ece9;font-size:11.5px;vertical-align:top}'+
    '.tf-en{direction:ltr;text-align:left}'+
    '.tf-ar{direction:rtl;text-align:right}'+
    '.tf-p{margin:0 0 2.8mm;text-align:justify}'+
    '.tf-sign{display:flex;justify-content:space-between;margin-top:5mm;font-size:12px}'+
    '.tf-sign div{width:45%;border-top:1px solid #333;padding-top:2.5mm;text-align:center}'+
    '.tf-box{border:1px solid #d8e2de;border-radius:7px;padding:6px 11px;background:#f7faf9;margin-bottom:3.5mm}'+
    'table.tf-eval{width:100%;border-collapse:collapse;margin-bottom:3.5mm;border:1px solid #d8e2de}'+
    'table.tf-eval th{background:#014D3D;color:#fff;padding:4px 6px;font-size:10px;text-align:center}'+
    'table.tf-eval td{padding:4px 6px;border-bottom:1px solid #e5ece9;font-size:10px;text-align:center}'+
    '.tf-chk{display:inline-block;width:12px;height:12px;border:1.5px solid #014D3D;border-radius:3px;margin-inline-start:6px;vertical-align:middle}'+
    '.tf-chk.on{background:#014D3D}'+
    '</style>';

  function tfWrap(titleAr, titleEn, bodyHtml){
    return DOC_CSS +
      '<div class="doc">'+
        '<img class="lh-head" src="'+HEADER_IMG+'">'+
        '<div class="doc-body">'+
          '<div class="doc-title">'+esc(titleAr)+(titleEn?'<span class="en">'+esc(titleEn)+'</span>':'')+'</div>'+
          bodyHtml+
        '</div>'+
        '<img class="lh-foot" src="'+FOOTER_IMG+'">'+
      '</div>';
  }

  function tfInfoTable(e){
    function cell(lbl, val){ return '<td class="tf-lbl">'+lbl+'</td><td class="tf-val">'+esc(val||'\u2014')+'</td>'; }
    return '<div class="tf-info-title">بيانات الموظف</div>'+
      '<table class="tf-info"><tr>'+
        cell('الاسم', e.nameAr||e.nameEn)+cell('الجنسية', e.nationality||e.nat)+
      '</tr><tr>'+
        cell('رقم الهوية/الإقامة', e.iqamaNo||e.iqama)+cell('الرقم الوظيفي', e.empNo)+
      '</tr><tr>'+
        cell('القسم/الإدارة', e.department||e.dept)+cell('المسمى الوظيفي', e.jobTitle)+
      '</tr></table>';
  }

  function tfBiInfoTable(e, joinISO){
    function row(en, ar, enVal, arVal){
      return '<tr><td class="tf-ar" style="width:22%"><b>'+ar+'</b></td><td class="tf-ar" style="width:28%">'+esc(arVal)+'</td>'+
             '<td class="tf-en" style="width:28%">'+esc(enVal)+'</td><td class="tf-en" style="width:22%"><b>'+en+'</b></td></tr>';
    }
    var name = e.nameAr||e.nameEn||'\u2014';
    var badge = e.empNo||'\u2014';
    var dept = e.department||e.dept||'\u2014';
    var job = e.jobTitle||'\u2014';
    return '<table class="tf-bi">'+
      row('To:', 'إلى:', name, name) +
      row('Badge #', 'الرقم الوظيفي:', badge, badge) +
      row('Department:', 'القسم:', dept, dept) +
      row('Job Title:', 'الوظيفة:', job, job) +
      row('Joining Date:', 'تاريخ المباشرة:', tfDEn(joinISO), tfD(joinISO)) +
      '</table>';
  }

  /* ============================================================
     1) نموذج مباشرة عمل
     ============================================================ */
  window.tfPrintOnboarding = function(){
    var e = tfRequireEmp(); if(!e) return;
    var manager = (document.getElementById('TF1_MGR')||{}).value || e.manager || '\u2014';
    var joinISO = (document.getElementById('TF1_JOIN')||{}).value || e.contractJoin || e.join || e.joinDate || '';
    var firstTime = document.getElementById('TF1_FIRST') ? document.getElementById('TF1_FIRST').checked : true;
    var leaveType = (document.getElementById('TF1_LVTYPE')||{}).value || '';

    var body =
      tfInfoTable(e) +
      '<div class="tf-box"><b>تاريخ المباشرة:</b> '+tfD(joinISO)+'</div>'+
      '<p class="tf-p">المكرم/ بناءً على إشعار التوظيف، نحيطكم علماً بأن الموظف الموضح بياناته أعلاه قد باشر العمل لدينا في شركة حلول أريبا لخدمات الأعمال — قسم '+esc(e.department||e.dept||'')+'.</p>'+
      '<p class="tf-p">الموظف باشر العمل في التاريخ المحدد وذلك يوم: <b>'+tfD(joinISO)+'</b>.</p>'+
      '<div class="tf-sign"><div>المدير المباشر: '+esc(manager)+'<br>التوقيع: ________________</div><div>التاريخ: '+tfD(new Date())+'</div></div>'+
      '<div class="tf-box" style="margin-top:8mm">'+
        '<span class="tf-chk'+(firstTime?' on':'')+'"></span> مباشرة عمل لأول مرة &nbsp;&nbsp;&nbsp; '+
        '<span class="tf-chk'+(!firstTime?' on':'')+'"></span> مباشرة عمل بعد العودة من إجازة'+(leaveType?(' ('+esc(leaveType)+')'):'')+
      '</div>'+
      '<div class="tf-sign"><div>شؤون الموظفين<br>التوقيع: ________________</div><div>التاريخ: ________________</div></div>'+
      '<div class="tf-sign" style="margin-top:14mm"><div>اعتماد الرئيس التنفيذي<br>التوقيع: ________________</div><div>التاريخ: ________________</div></div>';

    if(typeof window.printHtml === 'function') window.printHtml('مباشرة عمل \u2014 '+(e.nameAr||''), tfWrap('مباشرة عمل','Onboarding Notice', body));
  };

  /* ============================================================
     2) نموذج استلام عهدة تقنية
     ============================================================ */
  window.tfAddCustodyRow = function(){
    var box = document.getElementById('TF2_ROWS'); if(!box) return;
    var row = document.createElement('div');
    row.setAttribute('data-tf2row','1');
    row.style.cssText = 'display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:6px;margin-bottom:6px';
    row.innerHTML =
      '<input placeholder="اسم العهدة (لابتوب، جوال...)" data-tf2-name style="padding:6px;border:1px solid var(--bd);border-radius:6px;background:var(--c2);color:var(--tx);font-size:11px">'+
      '<input placeholder="الموديل / الرقم التسلسلي" data-tf2-serial style="padding:6px;border:1px solid var(--bd);border-radius:6px;background:var(--c2);color:var(--tx);font-size:11px">'+
      '<input placeholder="الحالة (جديد/مستعمل)" data-tf2-cond style="padding:6px;border:1px solid var(--bd);border-radius:6px;background:var(--c2);color:var(--tx);font-size:11px">'+
      '<button type="button" class="btn bsm" style="color:var(--rd)" onclick="this.parentNode.remove()"><i class="ti ti-trash"></i></button>';
    box.appendChild(row);
  };

  window.tfPrintCustody = function(){
    var e = tfRequireEmp(); if(!e) return;
    var rows = [];
    document.querySelectorAll('#TF2_ROWS [data-tf2row]').forEach(function(r){
      var n = r.querySelector('[data-tf2-name]').value.trim();
      var s = r.querySelector('[data-tf2-serial]').value.trim();
      var c = r.querySelector('[data-tf2-cond]').value.trim();
      if(n) rows.push({n:n, s:s, c:c});
    });
    if(!rows.length){ if(typeof toast==='function') toast('أضف بند عهدة واحد على الأقل', 'ter'); return; }

    var itemsHtml = rows.map(function(r,i){
      return '<tr><td>'+(i+1)+'</td><td>'+esc(r.n)+'</td><td>'+esc(r.s||'\u2014')+'</td><td>'+esc(r.c||'\u2014')+'</td></tr>';
    }).join('');

    var body =
      tfInfoTable(e) +
      '<table class="tf-bi"><tr><th style="width:8%">م</th><th>اسم العهدة</th><th>الموديل / الرقم التسلسلي</th><th>الحالة</th></tr>'+itemsHtml+'</table>'+
      '<p class="tf-p">أقر أنا الموظف الموضح بياناته أعلاه باستلامي العهدة التقنية المذكورة أعلاه من شركة حلول أريبا لخدمات الأعمال، وأتعهد بالمحافظة عليها واستخدامها في أعمال الشركة فقط، وإعادتها بحالة جيدة عند طلبها أو عند انتهاء علاقتي التعاقدية مع الشركة لأي سبب كان.</p>'+
      '<div class="tf-sign"><div>الموظف: '+esc(e.nameAr||'')+'<br>التوقيع: ________________</div><div>التاريخ: ________________</div></div>'+
      '<div class="tf-sign" style="margin-top:10mm"><div>عن قسم تقنية المعلومات<br>التوقيع: ________________</div><div>التاريخ: ________________</div></div>';

    if(typeof window.printHtml === 'function') window.printHtml('استلام عهدة تقنية \u2014 '+(e.nameAr||''), tfWrap('نموذج استلام عهدة تقنية','IT Custody Receipt', body));
  };

  /* ============================================================
     3) نموذج تمديد فترة التجربة
     ============================================================ */
  window.tfPrintExtension = function(){
    var e = tfRequireEmp(); if(!e) return;
    var joinISO = (document.getElementById('TF3_JOIN')||{}).value || e.contractJoin || e.join || '';
    var newEndISO = (document.getElementById('TF3_END')||{}).value || '';
    if(!newEndISO){ if(typeof toast==='function') toast('حدد تاريخ نهاية التمديد الجديد', 'ter'); return; }

    var body =
      tfBiInfoTable(e, joinISO) +
      '<p class="tf-p tf-en">Greetings ,,</p><p class="tf-p tf-ar">تحية طيبة وبعد,,</p>'+
      '<p class="tf-p tf-en">Referring to the employment contract concluded with you on '+tfDEn(joinISO)+', please be informed that it has been decided to extend your probationary period to another period ending on '+tfDEn(newEndISO)+'.</p>'+
      '<p class="tf-p tf-ar">إشارة إلى عقد العمل المبرم معكم بتاريخ '+tfD(joinISO)+'، نرجو العلم بأنه قد تقرر تمديد فترة التجربة الخاصة بكم إلى فترة أخرى تنتهي بتاريخ '+tfD(newEndISO)+'.</p>'+
      '<p class="tf-p tf-en">Accordingly, you are kindly requested to receive this notice and provide us with a signed copy of it.</p>'+
      '<p class="tf-p tf-ar">وعليه، يرجى منكم التكرم بإستلام هذا الإشعار وموافاتنا بنسخة موقعة منه.</p>'+
      '<p class="tf-p tf-en">With our best wishes for your success,,</p><p class="tf-p tf-ar">مع وافر أمنياتنا لكم بالتوفيق والنجاح,,</p>'+
      '<div style="text-align:center;margin:8mm 0 10mm"><b>مدير الموارد البشرية<br>Human Resources Manager</b></div>'+
      '<div class="tf-box">'+
        '<p class="tf-p tf-en" style="margin-bottom:2mm">I ( '+esc(e.nameAr||e.nameEn||'')+' ) acknowledge my agreement to extend the trial period in accordance with the above.</p>'+
        '<p class="tf-p tf-ar">أقر أنا ( '+esc(e.nameAr||'')+' ) بموافقتي على تمديد فترة التجربة وفقاً لما ورد أعلاه.</p>'+
      '</div>'+
      '<div class="tf-sign"><div>Signature: ________________<br>التوقيع: ________________</div><div>Date: ________________<br>التاريخ: ________________</div></div>';

    if(typeof window.printHtml === 'function') window.printHtml('تمديد فترة التجربة \u2014 '+(e.nameAr||''), tfWrap('إشعار تمديد فترة التجربة','Probationary Period Extension', body));
  };

  /* ============================================================
     4) نموذج إشعار بإنتهاء التعاقد (فترة التجربة)
     ============================================================ */
  window.tfPrintTermination = function(){
    var e = tfRequireEmp(); if(!e) return;
    var joinISO = (document.getElementById('TF4_JOIN')||{}).value || e.contractJoin || e.join || '';
    var lastISO = (document.getElementById('TF4_LAST')||{}).value || '';
    if(!lastISO){ if(typeof toast==='function') toast('حدد تاريخ آخر يوم عمل', 'ter'); return; }

    var body =
      tfBiInfoTable(e, joinISO) +
      '<p class="tf-p tf-en">Greetings ,,</p><p class="tf-p tf-ar">تحية طيبة وبعد,,</p>'+
      '<p class="tf-p tf-en">Referring to the employment contract concluded with you on '+tfDEn(joinISO)+', please be informed that it has been decided to terminate your probationary period and your last working date will be '+tfDEn(lastISO)+'.</p>'+
      '<p class="tf-p tf-ar">إشارة إلى عقد العمل المبرم معكم بتاريخ '+tfD(joinISO)+'، نرجو العلم بأنه قد تقرر إنهاء فترة التجربة الخاصة بكم على أن يكون آخر يوم عمل لكم تحت التجربة بتاريخ '+tfD(lastISO)+'.</p>'+
      '<p class="tf-p tf-en">Accordingly, you are kindly requested to receive this notice and provide us with a signed copy of it.</p>'+
      '<p class="tf-p tf-ar">وعليه، يرجى منكم التكرم بإستلام هذا الإشعار وموافاتنا بنسخة موقعة منه.</p>'+
      '<p class="tf-p tf-en">With our best wishes for your success,,</p><p class="tf-p tf-ar">مع وافر أمنياتنا لكم بالتوفيق والنجاح,,</p>'+
      '<div style="text-align:center;margin:8mm 0 10mm"><b>مدير الموارد البشرية<br>Human Resources Manager</b></div>'+
      '<div class="tf-box">'+
        '<p class="tf-p tf-en" style="margin-bottom:2mm">I ( '+esc(e.nameAr||e.nameEn||'')+' ) acknowledge receipt of the termination notice.</p>'+
        '<p class="tf-p tf-ar">أقر أنا ( '+esc(e.nameAr||'')+' ) بإستلام إشعار الإنهاء.</p>'+
      '</div>'+
      '<div class="tf-sign"><div>Signature: ________________<br>التوقيع: ________________</div><div>Date: ________________<br>التاريخ: ________________</div></div>';

    if(typeof window.printHtml === 'function') window.printHtml('إشعار إنهاء فترة التجربة \u2014 '+(e.nameAr||''), tfWrap('إشعار إنهاء فترة التجربة','Probationary Period Termination', body));
  };

  /* ============================================================
     5) نموذج إخلاء طرف
     ============================================================ */
  window.tfPrintClearance = function(){
    var e = tfRequireEmp(); if(!e) return;
    var joinISO = (document.getElementById('TF5_JOIN')||{}).value || e.contractJoin || e.join || '';
    var lastISO = (document.getElementById('TF5_LAST')||{}).value || '';
    var reason = (document.getElementById('TF5_REASON')||{}).value || 'resign';
    var otherTxt = (document.getElementById('TF5_OTHER')||{}).value || '';
    if(!lastISO){ if(typeof toast==='function') toast('حدد تاريخ آخر يوم عمل', 'ter'); return; }

    var body =
      tfInfoTable(e) +
      '<div class="tf-box">'+
        '<div style="margin-bottom:4px"><b>تاريخ المباشرة:</b> '+tfD(joinISO)+'</div>'+
        '<div><b>تاريخ آخر يوم عمل:</b> '+tfD(lastISO)+'</div>'+
      '</div>'+
      '<div class="tf-box">أسباب إخلاء الطرف: '+
        '<span class="tf-chk'+(reason==='resign'?' on':'')+'"></span> استقالة &nbsp;&nbsp; '+
        '<span class="tf-chk'+(reason==='end'?' on':'')+'"></span> انتهاء العقد &nbsp;&nbsp; '+
        '<span class="tf-chk'+(reason==='other'?' on':'')+'"></span> أخرى'+(reason==='other'&&otherTxt?(': '+esc(otherTxt)):'')+
      '</div>'+
      '<p class="tf-p">نقر نحن شركة حلول أريبا لخدمات الأعمال بأن الموظف المذكور بياناته أعلاه قد أنهى أعماله في الشركة وسلّم جميع العهد التي تخصه، وليس عليه أي مستحقات أو متعلقات أو التزامات.</p>'+
      '<p class="tf-p">وعلى هذا تم إخلاء طرف الموظف.</p>'+
      '<div class="tf-sign" style="margin-top:16mm"><div><b>الموارد البشرية</b><br>التوقيع: ________________</div><div>التاريخ: '+tfD(new Date())+'</div></div>';

    if(typeof window.printHtml === 'function') window.printHtml('إخلاء طرف \u2014 '+(e.nameAr||''), tfWrap('إخلاء الطرف','Final Clearance', body));
  };

  /* ============================================================
     6) شهادة خبرة
     ============================================================ */
  window.tfPrintExperience = function(){
    var e = tfRequireEmp(); if(!e) return;
    var startISO = (document.getElementById('TF6_START')||{}).value || e.contractJoin || e.join || '';
    var stillWorking = document.getElementById('TF6_STILL') ? document.getElementById('TF6_STILL').checked : true;
    var endISO = (document.getElementById('TF6_END')||{}).value || '';
    var nature = (document.getElementById('TF6_NATURE')||{}).value || 'دوام كامل';
    var certNo = (document.getElementById('TF6_NO')||{}).value || ('AR-'+(e.empNo||'')+'-'+new Date().getFullYear());

    var body =
      '<div class="meta-row"><div>الصادر: '+esc(certNo)+'</div><div>التاريخ: '+tfD(new Date())+'</div></div>'+
      '<p class="tf-p">تشهد شركة حلول أريبا لخدمات الأعمال، بأن السيد/ة <b>'+esc(e.nameAr||e.nameEn||'')+'</b>، '+esc(e.nationality||e.nat||'')+' الجنسية، رقم الهوية ('+esc(e.iqamaNo||e.iqama||'')+')، عمل لدينا بوظيفة (<b>'+esc(e.jobTitle||'')+'</b>) بحسب البيانات أدناه:</p>'+
      '<table class="tf-info">'+
        '<tr><td class="tf-lbl">نوع العقد</td><td class="tf-val" colspan="3">عقد عمل</td></tr>'+
        '<tr><td class="tf-lbl">طبيعة التعاقد</td><td class="tf-val" colspan="3">'+esc(nature)+'</td></tr>'+
        '<tr><td class="tf-lbl">بداية التعاقد</td><td class="tf-val">'+tfD(startISO)+'</td>'+
        '<td class="tf-lbl">نهاية التعاقد</td><td class="tf-val">'+(stillWorking?'لا يزال على رأس العمل حتى تاريخه':tfD(endISO))+'</td></tr>'+
      '</table>'+
      '<p class="tf-p">وخلال فترة عمله لدينا أنجز المهام الموكلة له، وقد كان حسن السيرة والسلوك.</p>'+
      '<p class="tf-p">شاكرين له جهوده خلال تلك الفترة مع تمنياتنا له بالتوفيق.</p>'+
      '<p class="tf-p">وقد تم إعطاؤه هذه الشهادة بناءً على طلبه وذلك دون أدنى مسؤولية على الشركة.</p>'+
      '<p class="tf-p">وتقبلوا أطيب التحايا والتقدير,,,</p>'+
      '<div style="margin-top:10mm"><b>مدير الموارد البشرية</b></div>';

    if(typeof window.printHtml === 'function') window.printHtml('شهادة خبرة \u2014 '+(e.nameAr||''), tfWrap('شهادة خبرة', '', body));
  };

  /* ============================================================
     7) نموذج تقييم فترة التجربة
     ============================================================ */
  var TF7_CRITERIA = [
    {en:'Technical Knowledge in his role', ar:'المعرفة الفنية في مجال عمله'},
    {en:'Adhering to the Company Rules & Regulations', ar:'الإلتزام بقوانين وأنظمة الشركة'},
    {en:'Quality of achieved work', ar:'جودة مخرجات العمل'},
    {en:'Employee relation with his manager & co-employees', ar:'علاقة الموظف مع إدارته وزملائه'},
    {en:'Employee ability to learn, develop & initiate', ar:'القدرة على التعلم والتطور والمبادرة'}
  ];
  var TF7_LABELS = {0:'غير مرضٍ',50:'أقل من التوقعات',70:'يحقق التوقعات',90:'يفوق التوقعات',100:'متميز'};

  window.tfBuildEvalRows = function(){
    var box = document.getElementById('TF7_ROWS'); if(!box || box.__built) return;
    box.__built = true;
    box.innerHTML = TF7_CRITERIA.map(function(c,i){
      return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'+
        '<div style="flex:1;font-size:11px">'+esc(c.ar)+'</div>'+
        '<select data-tf7-score="'+i+'" style="padding:5px;border:1px solid var(--bd);border-radius:6px;background:var(--c2);color:var(--tx);font-size:11px;width:170px">'+
          '<option value="0">غير مرضٍ (0%)</option>'+
          '<option value="50">أقل من التوقعات (50%)</option>'+
          '<option value="70" selected>يحقق التوقعات (70%)</option>'+
          '<option value="90">يفوق التوقعات (90%)</option>'+
          '<option value="100">متميز (100%)</option>'+
        '</select>'+
      '</div>';
    }).join('');
  };

  window.tfPrintEvaluation = function(){
    var e = tfRequireEmp(); if(!e) return;
    var joinISO = (document.getElementById('TF7_JOIN')||{}).value || e.contractJoin || e.join || '';
    var endISO = (document.getElementById('TF7_END')||{}).value || '';
    var recText = (document.getElementById('TF7_REC')||{}).value || '';
    var decision = (document.querySelector('input[name="tf7dec"]:checked')||{}).value || '';

    var scores = [];
    document.querySelectorAll('#TF7_ROWS [data-tf7-score]').forEach(function(sel){ scores.push(Number(sel.value)||0); });
    if(!scores.length) scores = [70,70,70,70,70];
    var total = Math.round(scores.reduce(function(a,b){return a+b;},0)/scores.length);

    var rowsHtml = TF7_CRITERIA.map(function(c,i){
      var sc = scores[i]||0;
      return '<tr><td>'+(i+1)+'</td><td style="text-align:right;padding-right:8px">'+esc(c.en)+' <span dir="rtl" style="display:block;color:#555">'+esc(c.ar)+'</span></td><td>'+sc+'%</td><td>'+(TF7_LABELS[sc]||'')+'</td></tr>';
    }).join('');

    var body =
      '<p class="tf-p tf-en">The mentioned employee below is about to complete his probationary period which will end on ('+tfDEn(endISO)+'), hence we appreciate filling up this form and returning it to HR before that date.</p>'+
      '<p class="tf-p tf-ar">حيث أن الموظف الموضحة بياناته أدناه قد أوشك على إكمال فترة التجربة والتي تنتهي بتاريخ ('+tfD(endISO)+')، وعليه نرجو التكرم بتعبئة هذا النموذج وإعادته لإدارة الموارد البشرية قبل ذلك التاريخ.</p>'+
      tfBiInfoTable(e, joinISO) +
      '<table class="tf-eval"><tr><th>#</th><th>Evaluation Criteria / معيار التقييم</th><th>Score<br>الدرجة</th><th>Rating<br>التقييم</th></tr>'+rowsHtml+
        '<tr style="font-weight:800;background:#f0f6f4"><td colspan="2">Total / المجموع</td><td colspan="2">'+total+'%</td></tr>'+
      '</table>'+
      '<div class="tf-box"><b>توصيات وإعتماد المدير المباشر / Line Manager Recommendation:</b><div style="margin-top:4px;min-height:14mm">'+esc(recText)+'</div></div>'+
      '<div class="tf-box"><b>القرار النهائي / Final Decision:</b><br>'+
        '<span class="tf-chk'+(decision==='appoint'?' on':'')+'"></span> تثبيت الموظف / Appoint the employee &nbsp;&nbsp; '+
        '<span class="tf-chk'+(decision==='terminate'?' on':'')+'"></span> إنهاء خدمته / Terminate employee &nbsp;&nbsp; '+
        '<span class="tf-chk'+(decision==='extend'?' on':'')+'"></span> تمديد فترة التجربة / Extend the Probation'+
      '</div>'+
      '<div class="tf-sign"><div>المدير المباشر<br>التوقيع: ________________</div><div>مدير الموارد البشرية<br>التوقيع: ________________</div></div>';

    if(typeof window.printHtml === 'function') window.printHtml('تقييم فترة التجربة \u2014 '+(e.nameAr||''), tfWrap('نموذج تقييم فترة التجربة','Probationary Period Evaluation Form', body));
  };

  /* ============================================================
     بناء الصفحة والقائمة الجانبية (إضافة فقط)
     ============================================================ */
  function tfPopulateEmpSelect(){
    var sel = document.getElementById('TFE');
    if(!sel) return;
    var cur = sel.value;
    var list = tfEmps();
    sel.innerHTML = '<option value="">— اختر الموظف —</option>' + list.map(function(e){
      return '<option value="'+esc(e.id)+'">'+esc(e.nameAr||e.nameEn||e.id)+'</option>';
    }).join('');
    if(cur) sel.value = cur;
  }

  function tfCard(title, icon, extraHtml, btnLabel, onclickFn){
    return '<div class="card" style="padding:12px">'+
      '<div class="ct" style="margin-bottom:8px"><i class="ti '+icon+'"></i> '+title+'</div>'+
      (extraHtml||'')+
      '<button class="btn bgr bsm" style="margin-top:8px" onclick="'+onclickFn+'()"><i class="ti ti-printer"></i> '+(btnLabel||'معاينة وطباعة')+'</button>'+
    '</div>';
  }

  function tfField(labelTxt, innerHtml){
    return '<div style="margin-bottom:6px"><label style="font-size:10px;color:var(--mu);font-weight:600;display:block;margin-bottom:2px">'+labelTxt+'</label>'+innerHtml+'</div>';
  }

  var TF_INPUT_STY = 'padding:6px;border:1px solid var(--bd);border-radius:6px;background:var(--c2);color:var(--tx);font-size:12px;width:100%';

  function tfBuildPage(){
    var page = document.createElement('div');
    page.className = 'pg';
    page.id = 'pg-forms';

    var cardsHtml =
      tfCard('مباشرة عمل', 'ti-login-2',
        tfField('اسم المدير المباشر', '<input id="TF1_MGR" style="'+TF_INPUT_STY+'">') +
        tfField('تاريخ المباشرة', '<input type="date" id="TF1_JOIN" style="'+TF_INPUT_STY+'">') +
        '<label style="font-size:11px;display:flex;align-items:center;gap:6px;margin-top:4px"><input type="checkbox" id="TF1_FIRST" checked> مباشرة لأول مرة</label>'+
        tfField('نوع الإجازة (لو عائد من إجازة)', '<input id="TF1_LVTYPE" placeholder="سنوية / مرضية / أمومة..." style="'+TF_INPUT_STY+'">'),
        'طباعة نموذج المباشرة', 'tfPrintOnboarding') +

      tfCard('استلام عهدة تقنية', 'ti-device-laptop',
        '<div id="TF2_ROWS"></div>'+
        '<button type="button" class="btn bsm" onclick="tfAddCustodyRow()" style="color:var(--gr);margin-top:4px"><i class="ti ti-plus"></i> إضافة عهدة</button>',
        'طباعة نموذج العهدة', 'tfPrintCustody') +

      tfCard('تمديد فترة التجربة', 'ti-calendar-plus',
        tfField('تاريخ بداية العقد', '<input type="date" id="TF3_JOIN" style="'+TF_INPUT_STY+'">') +
        tfField('تاريخ نهاية التمديد الجديد', '<input type="date" id="TF3_END" style="'+TF_INPUT_STY+'">'),
        'طباعة إشعار التمديد', 'tfPrintExtension') +

      tfCard('إشعار بإنتهاء التعاقد (فترة التجربة)', 'ti-calendar-x',
        tfField('تاريخ بداية العقد', '<input type="date" id="TF4_JOIN" style="'+TF_INPUT_STY+'">') +
        tfField('تاريخ آخر يوم عمل', '<input type="date" id="TF4_LAST" style="'+TF_INPUT_STY+'">'),
        'طباعة إشعار الإنهاء', 'tfPrintTermination') +

      tfCard('إخلاء طرف', 'ti-logout',
        tfField('تاريخ المباشرة', '<input type="date" id="TF5_JOIN" style="'+TF_INPUT_STY+'">') +
        tfField('تاريخ آخر يوم عمل', '<input type="date" id="TF5_LAST" style="'+TF_INPUT_STY+'">') +
        tfField('سبب إخلاء الطرف', '<select id="TF5_REASON" style="'+TF_INPUT_STY+'"><option value="resign">استقالة</option><option value="end">انتهاء العقد</option><option value="other">أخرى</option></select>') +
        tfField('توضيح (لو أخرى)', '<input id="TF5_OTHER" style="'+TF_INPUT_STY+'">'),
        'طباعة إخلاء الطرف', 'tfPrintClearance') +

      tfCard('شهادة خبرة', 'ti-certificate',
        tfField('تاريخ بداية التعاقد', '<input type="date" id="TF6_START" style="'+TF_INPUT_STY+'">') +
        '<label style="font-size:11px;display:flex;align-items:center;gap:6px;margin:4px 0"><input type="checkbox" id="TF6_STILL" checked onchange="document.getElementById(\'TF6_END\').disabled=this.checked"> لا يزال على رأس العمل</label>'+
        tfField('تاريخ نهاية التعاقد (لو انتهى)', '<input type="date" id="TF6_END" disabled style="'+TF_INPUT_STY+'">') +
        tfField('طبيعة التعاقد', '<input id="TF6_NATURE" value="دوام كامل" style="'+TF_INPUT_STY+'">') +
        tfField('رقم الشهادة الصادر', '<input id="TF6_NO" placeholder="AR-000-2026" style="'+TF_INPUT_STY+'">'),
        'طباعة شهادة الخبرة', 'tfPrintExperience') +

      tfCard('نموذج تقييم فترة التجربة', 'ti-clipboard-check',
        tfField('تاريخ بداية العقد', '<input type="date" id="TF7_JOIN" style="'+TF_INPUT_STY+'">') +
        tfField('تاريخ نهاية فترة التجربة', '<input type="date" id="TF7_END" style="'+TF_INPUT_STY+'">') +
        '<div id="TF7_ROWS" style="margin-top:6px"></div>'+
        tfField('توصيات المدير المباشر', '<textarea id="TF7_REC" rows="2" style="'+TF_INPUT_STY+'"></textarea>') +
        '<div style="font-size:11px;display:flex;gap:10px;flex-wrap:wrap;margin-top:4px">'+
          '<label style="display:flex;align-items:center;gap:4px"><input type="radio" name="tf7dec" value="appoint"> تثبيت</label>'+
          '<label style="display:flex;align-items:center;gap:4px"><input type="radio" name="tf7dec" value="terminate"> إنهاء</label>'+
          '<label style="display:flex;align-items:center;gap:4px"><input type="radio" name="tf7dec" value="extend"> تمديد</label>'+
        '</div>',
        'طباعة نموذج التقييم', 'tfPrintEvaluation');

    page.innerHTML =
      '<div class="card" style="padding:12px;margin-bottom:12px">'+
        '<div class="ct" style="margin-bottom:8px"><i class="ti ti-user-search"></i> اختر الموظف (مشترك لكل النماذج)</div>'+
        '<select id="TFE" style="max-width:420px;width:100%"></select>'+
      '</div>'+
      '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px">'+cardsHtml+'</div>';

    var afterNode = document.getElementById('pg-set') || document.querySelector('.pg');
    if(afterNode && afterNode.parentNode) afterNode.parentNode.appendChild(page);
    else document.body.appendChild(page);

    tfPopulateEmpSelect();
    window.tfBuildEvalRows();
    window.tfAddCustodyRow();
  }

  var tfPageBuilt = false;
  function tfEnsurePage(){
    if(tfPageBuilt) return;
    if(!document.getElementById('pg-set')) return; // البرنامج لسه مش خلص تحميل
    tfBuildPage();
    tfPageBuilt = true;
  }

  /* ---------- إضافة عنصر القائمة الجانبية "نماذج" بدون تعديل buildNav الأصلية ---------- */
  function tfEnsureNavItem(){
    try{
      var nv = document.getElementById('NV');
      if(!nv || document.getElementById('ni-forms')) return;
      var ni = document.createElement('div');
      ni.className = 'ni';
      ni.id = 'ni-forms';
      ni.innerHTML = '<i class="ti ti-files"></i><span class="nl">نماذج</span>';
      ni.onclick = function(){ window.showPg('forms', ni); };
      nv.appendChild(ni);
    }catch(e){}
  }

  if(window.PG_INFO && typeof window.PG_INFO === 'object'){
    window.PG_INFO.forms = {ar:'النماذج', en:'Templates', ic:'ti-files'};
  }

  var oldShowPg70 = window.showPg;
  if(typeof oldShowPg70 === 'function' && !oldShowPg70.__v70){
    window.showPg = function(id, el){
      if(id === 'forms'){
        tfEnsurePage();
        document.querySelectorAll('.pg').forEach(function(p){ p.classList.remove('on'); });
        var pg = document.getElementById('pg-forms');
        if(pg) pg.classList.add('on');
        document.querySelectorAll('.ni').forEach(function(n){ n.classList.remove('on'); });
        if(el) el.classList.add('on'); else { var ni = document.getElementById('ni-forms'); if(ni) ni.classList.add('on'); }
        var ptt = document.getElementById('PTT'); if(ptt) ptt.textContent = 'النماذج';
        var ptIcon = document.getElementById('PT'); if(ptIcon){ var ic = ptIcon.querySelector('i'); if(ic) ic.className = 'ti ti-files'; }
        tfPopulateEmpSelect();
        return;
      }
      return oldShowPg70.apply(this, arguments);
    };
    window.showPg.__v70 = true;
  }

  tfEnsureNavItem();
  setInterval(tfEnsureNavItem, 1500);

  /* ---------- تصدير الدوال المساعدة الداخلية لاستخدامها في باتشات إضافية لاحقة (V71+) ---------- */
  window.tfEsc71 = esc;
  window.tfD71 = tfD;
  window.tfDEn71 = tfDEn;
  window.tfInfoTable71 = tfInfoTable;
  window.tfBiInfoTable71 = tfBiInfoTable;
  window.tfWrap71 = tfWrap;
  window.tfEmps71 = tfEmps;
  window.tfRequireEmp71 = tfRequireEmp;
})();
